import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{radiationFigure}from './rad1-figures.js?v=20261023-physicscomplete01';export function showRad1(spec='atoms',w={}){let[kind,card]=spec.split(':');renderDiagram(w.title||'Explore nuclear physics',w.label||'Original schematic · not to scale',radiationFigure({kind,state:card||'0',...w}).replaceAll('rad1-coral','rad1-view-coral').replaceAll('rad1-teal','rad1-view-teal').replaceAll('rad1-gold','rad1-view-gold'),'PHYSICS · ATOMIC STRUCTURE');}
